declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/bloodbank_v570.php';if(!bb570_enabled()){http_response_code(404);exit('Blood Bank module unavailable.');}$me=current_user();if(!$me&&function_exists('setting_bool')&&!setting_bool('bloodbank_v570_guest_requests',true)){header('Location: /login.php?next=/blood-request.php',true,302);exit;}$banks=bb570_banks(true);$flash='';$error='';$reqId=0;if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{csrf_check();$reqId=bb570_save_public_request($_POST,$me);$flash='Blood request submitted. Reference #'.$reqId.'. It will appear publicly only if enabled and verified by authorized staff.';}catch(Throwable $e){$error=$e->getMessage();}}bb570_public_header('Request Blood','Submit a blood request for review and coordination by authorized blood-bank staff.');?>
<main class="bb570-form-page"><section class="bb570-form-hero request"><div class="bb570-shell"><span>BLOOD REQUEST DESK</span><h1>Submit a blood request securely.</h1><p>Patient details remain private in the admin system. Public cards display only the blood group, hospital/area, urgency and units needed after verification.</p></div></section><div class="bb570-shell bb570-form-grid"><?php if($flash):?><div class="bb570-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="bb570-alert err"><?=e($error)?></div><?php endif;?><section class="bb570-form-card full"><div class="form-title"><span>REQUEST INFORMATION</span><h2>Blood requirement</h2></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="field-grid"><label>Patient name <small>(private)</small><input name="patient_name"></label><label>Hospital / facility<input name="hospital_name" required></label><label>Hospital area<input name="hospital_area"></label><label>Blood group<select name="blood_group" required><option value="">Choose</option><?php foreach(bb570_groups() as $g):?><option><?=e($g)?></option><?php endforeach;?></select></label><label>Component<select name="component"><?php foreach(bb570_components() as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach;?></select></label><label>Units needed<input type="number" min="1" max="20" name="units_needed" value="1" required></label><label>Urgency<select name="urgency"><option value="routine">Routine</option><option value="urgent" selected>Urgent</option><option value="emergency">Emergency</option></select></label><label>Needed by<input type="datetime-local" name="needed_at"></label><label>Preferred blood bank<select name="preferred_bank_id"><option value="">Any available center</option><?php foreach($banks as $b):?><option value="<?=(int)$b['id']?>"><?=e($b['name'])?></option><?php endforeach;?></select></label><label>Contact person<input name="contact_name" required value="<?=e($me['name']??'')?>"></label><label>Contact phone<input name="contact_phone" required value="<?=e($me['phone']??'')?>"></label><label>Contact email<input type="email" name="contact_email" value="<?=e($me['email']??'')?>"></label><label class="wide">Hospital / pickup address<textarea name="address" rows="2"></textarea></label><label>Latitude<input type="number" step="0.0000001" name="latitude"></label><label>Longitude<input type="number" step="0.0000001" name="longitude"></label><label class="wide">Clinical / coordination note <small>(private staff note)</small><textarea name="clinical_note" rows="3"></textarea></label></div><div class="consents"><label><input type="checkbox" name="is_public" value="1" checked> After staff verification, show an anonymized request card publicly to help find donors.</label><label><input type="checkbox" name="consent" value="1" required> I confirm I am authorized to submit this request and consent to secure handling of the provided information for blood-bank coordination.</label></div><button class="btn primary wide-btn">Submit Blood Request</button></form></section><aside class="bb570-side-note full-note"><h3>Important</h3><p>This portal coordinates requests and stock records; it does not replace hospital transfusion protocols. Blood group information, compatibility, component selection, screening, crossmatch and issue decisions must be confirmed by qualified medical/blood-bank staff.</p></aside></div></main><?php bb570_public_footer(); ?>
